mapper.select:
SELECT consume_id, consume_no, dept_id, dept_name, consume_type, consume_date, consume_user_id, consume_user_name, patient_name, patient_no, total_quantity, total_amount, status, remark, create_user_name, create_time FROM spd_dept_consume WHERE del_flag = 0
AND consume_no LIKE CONCAT('%', #{query.consumeNo}, '%')
AND dept_id = #{query.deptId}
AND consume_type = #{query.consumeType}
AND patient_name LIKE CONCAT('%', #{query.patientName}, '%')
AND patient_no LIKE CONCAT('%', #{query.patientNo}, '%')
AND status = #{query.status}
AND consume_date >= #{query.startTime}
AND consume_date <= #{query.endTime}
ORDER BY create_time DESC
